import React from 'react';

const Cards = ({ count }) => {
  return (
    <div className='cards'>
      {[...Array(count)].map((_, index) => (
        <div className='cards_content' key={index}>
          <div className='card'>
            <h3>No data</h3>
          </div>
          <h2>Goddess #{index + 1}</h2>
        </div>
      ))}
    </div>
  );
};

export default Cards;