import React, { useEffect, useRef, useState } from 'react';
import mapboxgl from 'mapbox-gl';
import { collection, getDocs } from 'firebase/firestore';
import { db } from '../../firebase-config';
import 'mapbox-gl/dist/mapbox-gl.css';
import markerIcon from '../images/pin_icon.png'; 
import open from '../images/open-in-new.svg'; 
import markerImage from '../images/icon.png'; 
import tg_icon from '../images/tg_icon.png'; 
import markerBackground from '../images/markerBackground.png'; 
import LoadingModal from '../LoadingModal'; 
import iconStar from '../images/icon_star.png'; 
import icon_x from '../images/icon_x.png'; 
import tg_start from '../images/tg_start.webp'; 

mapboxgl.accessToken = 'pk.eyJ1IjoidmxhZGlzbGF2c2lkIiwiYSI6ImNtMTg3enBiMjB3b3oyaXF6dGV5bXVtdzcifQ.HFXUF85RtWYTbbiC42vwvw';

const GlobesComponent = ({ mapRef }) => {
  const mapContainer = useRef(null);
  const markers = useRef([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (mapContainer.current && !mapRef.current) {
      const map = new mapboxgl.Map({
        container: mapContainer.current,
        style: 'mapbox://styles/vladislavsid/cm19f91mn028r01qog86a2c73',
        center: [25.4858, 42.7339], 
        zoom: 2,
        minZoom: 0.6,
        projection: 'globe',
      });

      mapRef.current = map;

      map.on('load', () => {
        fetchMarkersFromDB();
        addBulgariaMarker(); // Add the Bulgaria marker
        setLoading(false);
      });
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, [mapRef]);

  const fetchMarkersFromDB = async () => {
    try {
      const querySnapshot = await getDocs(collection(db, 'markers'));
      const markersData = querySnapshot.docs.map(doc => doc.data());
      markersData.forEach(markerData => {
        addMarker([markerData.lng, markerData.lat], false, markerData);
      });
    } catch (error) {
      console.error("Error fetching markers: ", error);
    }
  };

  const addMarker = (lngLat, draggable, markerData = {}) => {
    if (!lngLat || isNaN(lngLat[0]) || isNaN(lngLat[1])) {
      console.error("Invalid coordinates:", lngLat);
      return;
    }

    const markerElement = document.createElement('div');
    markerElement.style.backgroundImage = `url(${markerIcon})`;
    markerElement.style.width = '1.555vw';
    markerElement.style.height = '2.125vw';
    markerElement.style.backgroundSize = 'cover';

    const popupContent = `
      <div style="
        width: 7.776vw; 
        padding: 0.518vw; 
        border-radius: 8px; 
        background-color: transparent !important;
        color: #fff; 
        position: relative;
      ">
        <img src="${markerBackground}" alt="Marker" style="width: 16.96vw; height: 14.013vw; position: absolute; top: -5.3vw; left: -4.7vw;" />
        <img src="${markerData.image || markerImage}" alt="Marker" style="width: 2.5vw; height: 2.5vw; border-radius: 50%; position: absolute; z-index: 3; top: -1.5vw; left: 0vw;" />
        <h2 style="
          font-size: 1vw; 
          position: absolute; 
          z-index: 3; 
          top: -1.7vw; 
          left: 3vw;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          max-width: 5vw;
        ">${markerData.name || 'lizatron'}</h2>
        <a href="https://t.me/${markerData.telegram}" style="font-size: 1vw; color: #fff; display: flex; align-items: center; position: absolute; z-index: 3; top: 1.8vw; left: 0vw;">
          <img src="${tg_icon}" alt="" style="width: 0.8vw; height: 0.8vw; padding-right: 0.5vw; position: relative; top: 0.04vw;" />
          <span style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 3vw;">
            ${markerData.telegram || '@El1za4real'}
          </span>
          <img src="${open}" alt="" style="width: 1.2vw; height: 1.2vw; padding-left: 0.5vw; position: relative; top: -0.1vw;" />
        </a>
      </div>
    `;

    const popup = new mapboxgl.Popup({ offset: 25 }).setHTML(popupContent);

    new mapboxgl.Marker(markerElement, { draggable })
      .setLngLat(lngLat)
      .setPopup(popup)
      .addTo(mapRef.current);

    markers.current.push(markerElement);
  };

  const addBulgariaMarker = () => {
    const bulgariaCoordinates = [25.4858, 42.7339]; // Bulgaria's coordinates
    const markerElement = document.createElement('div');
    markerElement.style.backgroundImage = `url(${iconStar})`;
    markerElement.style.width = '2.2vw';
    markerElement.style.height = '2.125vw';
    markerElement.style.backgroundSize = 'cover';

    const popupContent = `
     <div style="
        width: 7.776vw; 
        padding: 0.518vw; 
        border-radius: 8px; 
        background-color: transparent !important;
        color: #fff; 
        position: relative;
      ">
        <img src="${markerBackground}" alt="Marker" style="width: 16.96vw; height: 17.013vw; position: absolute; top: -7.3vw; left: -4.7vw;" />
        <img src="${tg_start}" alt="Marker" style="width: 2.5vw; height: 2.5vw; border-radius: 50%; position: absolute; z-index: 3; top: -2.5vw; left: 0vw;" />
        <h2 style="
          font-size: 1vw; 
          position: absolute; 
          z-index: 3; 
          top: -2.7vw; 
          left: 3vw;
          white-space: nowrap;
          overflow: hidden;
          text-overflow: ellipsis;
          max-width: 5vw;
        ">${'lizatron'}</h2>
        <a href="https://t.me/El1za4real" style="font-size: 1vw; color: #fff; display: flex; align-items: center; position: absolute; z-index: 3; top: 0.5vw; left: 0vw;">
          <img src="${tg_icon}" alt="" style="width: 0.8vw; height: 0.8vw; padding-right: 0.5vw; position: relative; top: 0.04vw;" />
          <span style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 3vw;">
            lizatron
          </span>
          <img src="${open}" alt="" style="width: 1.2vw; height: 1.2vw; padding-left: 0.5vw; position: relative; top: -0.1vw;" />
        </a>
        <a href="https://x.com/TenderbiteArt" style="font-size: 1vw; color: #fff; display: flex; align-items: center; position: absolute; z-index: 3; top: 1.8vw; left: 0vw;">
          <img src="${icon_x}" alt="" style="width: 1.2vw; height: 1.2vw; padding-right: 0.5vw; position: relative; top: 0.04vw; left:-0.2vw" />
          <span style="white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 3vw;">
            TenderbiteArt
          </span>
          <img src="${open}" alt="" style="width: 1.2vw; height: 1.2vw; padding-left: 0.5vw; position: relative; top: -0.1vw;" />
        </a>
      </div>
    `;

    const popup = new mapboxgl.Popup({ offset: 25 }).setHTML(popupContent);

    new mapboxgl.Marker(markerElement)
      .setLngLat(bulgariaCoordinates)
      .setPopup(popup)
      .addTo(mapRef.current);
  };

  return (
    <div style={{ position: 'relative', width: '100%', height: '100%' }}>
      {loading && (
        <div style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.1) !important',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1000,
          color: '#fff',
          fontSize: '1.5em'
        }}>
          <LoadingModal/>
        </div>
      )}
      <div
        ref={mapContainer}
        style={{ width: '100%', height: '100%' }}
      />
    </div>
  );
};

export default GlobesComponent;