import React, { useState } from 'react';
import Cards from './cards';

function Sidebar() {
  const [activeSection, setActiveSection] = useState('Background');
  const [cardCount, setCardCount] = useState(13);

  const handleButtonClick = (section, count) => {
    setActiveSection(section);
    setCardCount(count);
  };

  return (
    <div>
      <main className="main-content">
        <div className="search-sort">
          <h3>Filter</h3>  
          <input type="text" placeholder="Search ID" />
          <div className="custom-select">
            <select>
              <option>Sort Random</option>
            </select>
            <svg width="24" height="24" viewBox="0 0 24 24">
              <path d="M7 10l5 5 5-5H7z"/>
            </svg>
          </div>
        </div>
        <div className="filters">
          <p>Filters: <span>{activeSection}</span></p>
        </div>
      </main>
      <div className='sidebar_and_content'>
        <aside className="sidebar">
          <ul>
            <li onClick={() => handleButtonClick('Background', 13)}>Background <span>+</span></li>
            <li onClick={() => handleButtonClick('Clothes', 10)}>Clothes <span>+</span></li>
            <li onClick={() => handleButtonClick('Eyes', 8)}>Eyes <span>+</span></li>
            <li onClick={() => handleButtonClick('Head', 5)}>Head <span>+</span></li>
            <li onClick={() => handleButtonClick('Mouth', 7)}>Mouth <span>+</span></li>
          </ul>
        </aside>
        {activeSection && <Cards count={cardCount} />}
      </div>
    </div>
  );
}

export default Sidebar;