import React, { useState, useEffect, useRef } from 'react';
import { collection, addDoc, getDocs } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { db, storage } from '../firebase-config';
import GlobesComponent from '../components/home/globes';
import MapComponent from '../components/home/map';
import Header from '../components/home/header';
import markerIconbutton from '../components/images/drop_my_pin.png';
import Modal from 'react-modal';
import mapboxgl from 'mapbox-gl';
import markerIcon from '../components/images/pin_icon.png';
import imageCompression from 'browser-image-compression';
import fix from '../components/images/fix.png';
import LoadingModal from '../components/LoadingModal'; 

Modal.setAppElement('#root');

function Home() {
  const [showMap, setShowMap] = useState(true);
  const [showFixButton, setShowFixButton] = useState(false);
  const [modalIsOpen, setModalIsOpen] = useState(false);
  const [policyModalIsOpen, setPolicyModalIsOpen] = useState(false);
  const [markerData, setMarkerData] = useState({ image: null, name: '', telegram: '' });
  const [allMarkers, setAllMarkers] = useState([]);
  const [markerCount, setMarkerCount] = useState(0);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  const mapRef = useRef(null);
  const draggableMarkerRef = useRef(null);

  useEffect(() => {
    fetchMarkers();
  }, []);

  const fetchMarkers = async () => {
    try {
      const querySnapshot = await getDocs(collection(db, 'markers'));
      const markers = querySnapshot.docs.map(doc => doc.data());
      setAllMarkers(markers);
      setMarkerCount(querySnapshot.size);
    } catch (error) {
      console.error("Error fetching markers: ", error);
    }
  };

  const handleAddMarker = () => {
    setPolicyModalIsOpen(true);
  };

  const handleAcceptPolicy = async () => {
    setPolicyModalIsOpen(false);
    if (mapRef.current) {
      const center = mapRef.current.getCenter();
      const markerElement = document.createElement('div');
      markerElement.style.backgroundImage = `url(${markerIcon})`;
      markerElement.style.width = '1.555vw';
      markerElement.style.height = '2.125vw';
      markerElement.style.backgroundSize = 'cover';
  
      const marker = new mapboxgl.Marker({
        element: markerElement,
        draggable: true
      })
        .setLngLat([center.lng, center.lat])
        .addTo(mapRef.current);
  
      draggableMarkerRef.current = marker;
      setShowFixButton(true);
    }
  };

  const handleFixMarker = () => {
    setModalIsOpen(true);
  };

  const handleModalSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (draggableMarkerRef.current) {
        const lngLat = draggableMarkerRef.current.getLngLat();
        if (markerData.image) {
          const compressedImage = await compressImage(markerData.image);
          const imageRef = ref(storage, `images/${Date.now()}-${compressedImage.name}`);
          const uploadResult = await uploadBytes(imageRef, compressedImage);
          const imageUrl = await getDownloadURL(uploadResult.ref);

          const newMarkerData = { 
            ...markerData, 
            image: imageUrl, 
            lng: lngLat.lng, 
            lat: lngLat.lat 
          };

          await addDoc(collection(db, 'markers'), newMarkerData);

          document.dispatchEvent(new CustomEvent('fixMarker', {
            detail: newMarkerData
          }));

          console.log("Документ успешно добавлен!");
          window.location.reload();
        } else {
          console.error("Изображение не загружено.");
        }
      } else {
        console.error("Маркер не инициализирован.");
      }
      setModalIsOpen(false);
      setShowFixButton(false);
    } catch (error) {
      console.error("Ошибка при добавлении документа: ", error);
    } finally {
      setLoading(false);
    }
  };

  const compressImage = async (file) => {
    const options = {
      maxSizeMB: 1,
      maxWidthOrHeight: 1920,
      useWebWorker: true,
    };

    try {
      const compressedFile = await imageCompression(file, options);
      return compressedFile;
    } catch (error) {
      console.error('Ошибка при сжатии изображения:', error);
      throw error;
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setMarkerData(prevState => ({ ...prevState, [name]: value }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setMarkerData(prevState => ({ ...prevState, image: file }));
    }
  };

  const handleSearchChange = (e) => {
    const value = e.target.value;
    setSearchTerm(value);

    const foundMarker = allMarkers.find(marker => marker.name.toLowerCase().includes(value.toLowerCase()));
    if (foundMarker && mapRef.current) {
      console.log("Найденный элемент:", foundMarker);
      mapRef.current.flyTo({
        center: [foundMarker.lng, foundMarker.lat],
        essential: true,
        zoom: 9
      });
    }
  };

  return (
    <div style={{ position: 'relative', width: '100%', height: '89.7vh' }}>
      <Header />
      <div className="container">
        <div>
          <h2>Marketcap</h2>
          <div className="item">
            <span className="circle"></span>
            <strong>$0</strong>
          </div>
        </div>
        <div>
          <h2>Population</h2>
          <div className="item">
            <span className="circle"></span>
            <strong>{markerCount}</strong>
          </div>
        </div>
      </div>
      <div className='search_botton_conteiner'>
        <input type="text" placeholder="Search Location" value={searchTerm} onChange={handleSearchChange} />
      </div>
      <button className='button-conteiner' onClick={handleAddMarker}>
        <div className='button-conteiner-content'>
          <img src={markerIconbutton} alt="Add Marker" />
        </div>
      </button>
      {showFixButton && (
        <div className='button-fixed'>
          <button onClick={handleFixMarker}><img src={fix} alt="Add Marker" /></button>
        </div>
      )}
      <Modal isOpen={policyModalIsOpen} onRequestClose={() => setPolicyModalIsOpen(false)} className="policy-modal" overlayClassName="custom-modal-overlay">
        <div>
          <h2>Policy!</h2>
          <p>By clicking on the “ACCEPT” button in this window, you agree to provide us with your social media information and your location coordinates!</p>
          <button onClick={handleAcceptPolicy} className="accept-button">Accept</button>
        </div>
      </Modal>
      {!loading && (
        <Modal isOpen={modalIsOpen} onRequestClose={() => setModalIsOpen(false)} className="custom-modal" overlayClassName="custom-modal-overlay">
          <form onSubmit={handleModalSubmit}>
            <label className="custom-file-upload">
              <input type="file" accept="image/*" onChange={handleImageChange} />
              Upload File
            </label>
            <input type="text" name="name" placeholder="Name" onChange={handleInputChange} required />
            <input type="text" name="telegram" placeholder="Telegram" onChange={handleInputChange} required />
            <button type="submit">Save</button>
          </form>
        </Modal>
      )}
      {loading && <LoadingModal />}
      <div className="toggle-buttons">
        <button
          className={`toggle-button ${showMap ? 'active' : ''}`}
          onClick={() => setShowMap(true)}
        >
          2D
        </button>
        <button
          className={`toggle-button ${!showMap ? 'active' : ''}`}
          onClick={() => setShowMap(false)}
        >
          3D
        </button>
      </div>
      {showMap ? <MapComponent mapRef={mapRef} /> : <GlobesComponent mapRef={mapRef}/>}
    </div>
  );
}

export default Home;