import React, { useState, useEffect, useRef } from 'react';
import title from '../images/title_elisa.png';
import tg from '../images/tg.png';
import x from '../images/x.png';
import ds from '../images/ds.png';
import { BrowserRouter as Router, Route, Switch, Link } from 'react-router-dom';

const Navbar = () => {
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);

  const toggleDropdown = () => {
    setDropdownOpen(!dropdownOpen);
  };

  const handleClickOutside = (event) => {
    if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
      setDropdownOpen(false);
    }
  };

  useEffect(() => {
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);


  return (
    <nav className="navbar_conteiner_home">
      <div className="navbar-logo"><img src={title} alt="" /></div>
      <ul className="navbar-menu">
        <li>
          <Link to="/gallery">Gallery</Link>
        </li>
        <li>
          <Link to="/">Map</Link>
        </li>
        <li ref={dropdownRef}>
            <a href="#distro" onClick={toggleDropdown}>More</a>
            {dropdownOpen && (
              <ul className="dropdown">
                <li><a href="#option1">Merch</a></li>
                <li><a href="#option2">about</a></li>
              </ul>
            )}
        </li>
      </ul>
      <div className="navbar-icons">
        <a href="https://x.com/E1isaNFT" className="icon-button"><img src={x} alt="" /></a>
        <a className="icon-button"><img src={tg} alt="" /></a>
        <a href="https://discord.com/invite/elisa" className="icon-button"><img src={ds} alt="" /></a>
      </div>
    </nav>
  );
}

export default Navbar;